"""pt — faith_b."""

T = {
"faith_071": ("O que significa o nome de Allah «As-Salam»?", ["A Paz, isento de todo defeito", "O Criador", "O Provedor", "O Poderoso"], "As-Salam figura entre os nomes enumerados no fim da sura Al-Hashr: Ele é a Paz, isento de toda imperfeição."),
"faith_072": ("Que atributos põe o versículo 59:22 junto ao nome de Allah, logo após «não há deus senão Ele»?", ["Conhecedor do oculto e do manifesto, o Clemente", "O Rei e o Guerreiro", "O Rico e o Generoso", "O Forte e o Veloz"], "«Ele é Allah, não há deus senão Ele, Conhecedor do oculto e do manifesto. Ele é o Clemente, o Misericordioso»."),
"faith_073": ("O que ordena o Alcorão fazer com os mais belos nomes de Allah?", ["Invocá-Lo por eles", "Apenas contá-los", "Escrevê-los nas portas", "Calá-los"], "«A Allah pertencem os nomes mais belos: invocai-O, pois, por eles»."),
"faith_074": ("Como apresenta a sura Ta-Ha os nomes de Allah?", ["«Allah! Não há deus senão Ele. Seus são os nomes mais belos»", "«Os Seus nomes estão ocultos»", "«Os Seus nomes são incontáveis»", "«Os Seus nomes são nove»"], "«Allah! Não há deus senão Ele. Seus são os nomes mais belos»."),
"faith_075": ("Que fórmula emprega o Alcorão para afastar toda semelhança com Allah?", ["«Não há nada semelhante a Ele; e Ele é o que tudo ouve, o que tudo vê»", "«É o maior dos reis»", "«É como a luz»", "«Ninguém O vê»"], "«Não há nada semelhante a Ele; e Ele é o que tudo ouve, o que tudo vê»."),
"faith_076": ("O que diz o Versículo do Trono sobre a sonolência e o sono?", ["Nem a sonolência nem o sono O afetam", "Dorme de noite", "Descansa ao sétimo dia", "Vela dia sim, dia não"], "«Não O afeta a sonolência nem o sono»."),
"faith_077": ("O que diz o Alcorão do conhecimento de Allah sobre a folha que cai?", ["Não cai uma folha sem que Ele o saiba", "Sabe-o depois", "Dizem-Lho os anjos", "Não está escrito"], "«Ele tem as chaves do oculto… não cai uma folha sem que Ele o saiba»."),
"faith_078": ("Do que está Allah mais perto do ser humano, segundo a sura Qaf?", ["Da sua veia jugular", "Da sua sombra", "Da sua voz", "Da sua casa"], "«Criámos o homem e sabemos o que a sua alma lhe sussurra; estamos mais perto dele do que a sua veia jugular»."),
"faith_079": ("Como descreve o Alcorão os anjos encarregados do Fogo?", ["Não desobedecem a Allah e fazem o que lhes é ordenado", "Alguns hesitam", "Dormem", "Escolhem"], "«…anjos duros e severos, que não desobedecem a Allah no que lhes ordena e fazem o que lhes é ordenado»."),
"faith_080": ("Como descreve o Alcorão os anjos perante a palavra de Allah?", ["Não O precedem no falar e agem por Sua ordem", "Discutem as Suas ordens", "Decidem sozinhos", "Calam-se sempre"], "«São antes servos honrados: não O precedem no falar e agem por Sua ordem»."),
"faith_081": ("Que anjo nomeia o Alcorão como aquele que fez descer a revelação sobre o coração do Profeta ﷺ?", ["Jibril (Gabriel)", "Mika'il (Miguel)", "Israfil", "Malik"], "«Diz: quem for inimigo de Jibril… foi ele quem a fez descer sobre o teu coração com a permissão de Allah»."),
"faith_082": ("Que outro anjo é nomeado junto a Jibril na sura Al-Baqara?", ["Mikal (Miguel)", "Israfil", "Ridwan", "Munkar"], "«Quem for inimigo de Allah, dos Seus anjos, dos Seus mensageiros, de Jibril e de Mikal…»"),
"faith_083": ("Que objetos de fé enumera o versículo 4:136?", ["Allah, o Seu Mensageiro, o Livro revelado e os Livros anteriores", "Só o Livro", "Só os profetas", "Só os anjos"], "«Ó crentes! Crede em Allah, no Seu mensageiro, no Livro que fez descer sobre o Seu mensageiro e no Livro que fez descer antes»."),
"faith_084": ("Que Livro menciona o Alcorão como dado a Dawud?", ["O Zabur (os Salmos)", "A Torá", "O Evangelho", "As Escrituras de Ibrahim"], "«…e demos a Dawud o Zabur»."),
"faith_085": ("Que sura tem o nome dos génios, que escutaram o Alcorão e creram?", ["Al-Jinn", "Al-Insan", "An-Nas", "Al-Furqan"], "«Diz: foi-me revelado que um grupo de génios escutou e disse: ouvimos uma recitação maravilhosa»."),
"faith_086": ("Para que foram criados os génios e os homens, segundo a sura Adh-Dhariyat?", ["Para que O adorem", "Para povoar a terra", "Para construir", "Para disputar"], "«Não criei os génios e os homens senão para que Me adorem»."),
"faith_087": ("O que diz o Alcorão acerca de toda alma e da morte?", ["Toda alma provará a morte", "Algumas almas não morrem", "A morte é uma dúvida", "A morte é um sono sem fim"], "«Toda alma provará a morte, e só no Dia da Ressurreição recebereis a vossa recompensa completa»."),
"faith_088": ("Em que estado sairão os homens, segundo a sura Az-Zalzala, para que lhes sejam mostradas as suas obras?", ["Em grupos separados", "Todos juntos numa só fila", "Adormecidos", "Silenciosos e invisíveis"], "«Nesse dia, os homens sairão em grupos separados para que lhes sejam mostradas as suas obras»."),
"faith_089": ("Como descreve a sura Al-Kahf o registo das obras no Último Dia?", ["Não deixa nada, pequeno nem grande, sem o consignar", "Só regista o grande", "É apagado", "É escrito pelos homens"], "«Dirão: “Ai de nós! Que livro é este, que não deixa nada, pequeno nem grande, sem o consignar?”»"),
"faith_090": ("O que diz o Alcorão dos membros do corpo no Dia do Juízo?", ["As mãos falarão e os pés testemunharão", "Ficarão mudos", "Estarão ocultos", "Serão transformados"], "«Nesse dia selaremos as suas bocas, e falar-nos-ão as suas mãos e testemunharão os seus pés sobre o que faziam»."),
"faith_091": ("Como qualifica o Alcorão a oração quanto ao seu horário?", ["Uma prescrição em tempos determinados", "Livre a qualquer hora", "Uma vez por semana", "Só de noite"], "«Certamente, a oração é para os crentes uma prescrição em tempos determinados»."),
"faith_092": ("Do que preserva a oração, segundo a sura Al-'Ankabut?", ["Da indecência e do reprovável", "Da fome", "Da doença", "Da viagem"], "«E estabelece a oração: a oração preserva da indecência e do reprovável»."),
"faith_093": ("Que oração assinala o Alcorão em particular como «a oração intermédia»?", ["É nomeada sem ser identificada, na ordem de guardar as orações", "Só a da alvorada", "Só a do ocaso", "A de sexta-feira"], "«Guardai as orações e a oração intermédia, e apresentai-vos perante Allah com humildade»."),
"faith_094": ("Com que fim ordena o Alcorão a oração, na sura Ta-Ha?", ["Para a lembrança de Allah", "Para descansar", "Para reunir-se", "Para contar as horas"], "«Eu sou Allah: não há deus senão Eu. Adora-Me, pois, e estabelece a oração para a Minha lembrança»."),
"faith_095": ("Que qualidade da oração abre a lista dos crentes que triunfam, em Al-Mu'minun?", ["A humildade (khushu') na oração", "O comprimento", "A rapidez", "O número"], "«Triunfaram os crentes: aqueles que na sua oração são humildes»."),
"faith_096": ("Que oração descreve a sura Al-Isra como «testemunhada» (mashhuda)?", ["A recitação da alvorada", "A oração do ocaso", "A do meio-dia", "A de sexta-feira"], "«Estabelece a oração desde o declínio do sol até à escuridão da noite, e a recitação da alvorada: a recitação da alvorada é testemunhada»."),
"faith_097": ("Com que duas coisas ordena o Alcorão buscar auxílio?", ["Com a paciência e a oração", "Com a força e a riqueza", "Com a viagem e o descanso", "Com o silêncio e a solidão"], "«Ó crentes! Buscai auxílio na paciência e na oração: Allah está com os pacientes»."),
"faith_098": ("Quantas rak'as tem a oração obrigatória do Dhuhr?", ["Quatro", "Duas", "Três", "Cinco"], "O Dhuhr, o 'Asr e o 'Isha têm cada um quatro rak'as obrigatórias; nisto as escolas concordam."),
"faith_099": ("Qual é a última das cinco orações obrigatórias do dia?", ["Al-'Isha", "Al-Fajr", "Al-Maghrib", "Al-'Asr"], "A ordem é: Fajr, Dhuhr, 'Asr, Maghrib, 'Isha."),
"faith_100": ("Como se chama a postura de prostração na oração?", ["O sujud", "O ruku'", "O qiyam", "O tashahhud"], "O qiyam é estar de pé, o ruku' a inclinação, o sujud a prostração e o tashahhud a posição sentada do testemunho."),
"faith_101": ("O que prevê o Alcorão para o doente ou o viajante durante o Ramadão?", ["Um número igual de dias a recuperar", "Nada", "Uma obrigação dupla", "Um jejum perpétuo"], "«Quem de vós estiver doente ou em viagem, que jejue um número igual de outros dias»."),
"faith_102": ("Que finalidade dá o Alcorão ao jejum prescrito?", ["Alcançar a piedade (taqwa)", "Emagrecer", "Poupar", "Descansar"], "«Foi-vos prescrito o jejum como foi prescrito aos que vos precederam, para que alcanceis a piedade»."),
"faith_103": ("O que responde Allah, no meio dos versículos do jejum, a quem pergunta pela Sua proximidade?", ["«Estou perto: respondo à súplica de quem Me invoca»", "«Esperai a noite»", "«Perguntai aos anjos»", "«Procurai longe»"], "«Quando os Meus servos te perguntarem por Mim, certamente estou perto: respondo à súplica de quem Me invoca quando Me invoca»."),
"faith_104": ("Quantas categorias de beneficiários do zakat enumera o Alcorão?", ["Oito", "Três", "Cinco", "Doze"], "«As esmolas são só para os pobres, os necessitados, os que nelas trabalham, aqueles cujos corações há que ganhar, a libertação de cativos, os endividados, a causa de Allah e o viajante»."),
"faith_105": ("Que efeito atribui o Alcorão ao zakat retirado dos bens?", ["Purifica e faz crescer", "Empobrece", "É simbólico", "Substitui a oração"], "«Toma dos seus bens uma esmola com que os purifiques e os acrescentes»."),
"faith_106": ("Que duas obrigações associa o Alcorão com mais frequência?", ["A oração e o zakat", "O jejum e a viagem", "A peregrinação e o comércio", "A leitura e a escrita"], "«Estabelecei a oração e dai o zakat; todo o bem que adiantardes para vós mesmos, encontrá-lo-eis junto a Allah»."),
"faith_107": ("O que diz o Alcorão que chega a Allah no sacrifício?", ["Nem a carne nem o sangue, mas a piedade do crente", "Só a carne", "Só o sangue", "O número de reses"], "«Nem a sua carne nem o seu sangue chegam a Allah, mas chega-Lhe a piedade da vossa parte»."),
"faith_108": ("Qual é a melhor provisão para a peregrinação, segundo o Alcorão?", ["A piedade", "O ouro", "Os víveres", "As montarias"], "«E tomai provisões; mas a melhor provisão é a piedade»."),
"faith_109": ("Que rito menciona o Alcorão à volta da Antiga Casa?", ["A circum-ambulação (tawaf)", "Correr pelo deserto", "Subir uma colina", "Jejuar ali"], "«…e que deem as voltas à volta da Antiga Casa»."),
"faith_110": ("Onde ordena o Alcorão invocar Allah, depois de partir de 'Arafat?", ["Junto a al-Mash'ar al-Haram, em Muzdalifa", "No monte Uhud", "Em Quba", "Em Taif"], "«Quando partirdes em massa de 'Arafat, lembrai Allah junto a al-Mash'ar al-Haram»."),
"faith_111": ("Que espécie de arrependimento pede o Alcorão aos crentes?", ["Um arrependimento sincero (tawba nasuh)", "Um arrependimento escrito", "Um arrependimento público", "Um arrependimento anual"], "«Ó crentes! Voltai-vos para Allah com um arrependimento sincero»."),
"faith_112": ("O que diz a sura Ash-Shura sobre a aceitação do arrependimento?", ["Ele é quem aceita o arrependimento dos Seus servos e perdoa as más obras", "O arrependimento não é aceite", "É preciso um intermediário", "É preciso esperar um ano"], "«Ele é quem aceita o arrependimento dos Seus servos, perdoa as más obras e sabe o que fazeis»."),
"faith_113": ("O que fazem aqueles que o Alcorão elogia, depois de cometerem uma falta?", ["Lembram Allah e pedem perdão", "Fogem", "Calam-se", "Culpam outros"], "«E aqueles que, quando cometem uma indecência ou se prejudicam a si mesmos, lembram Allah e pedem perdão pelos seus pecados»."),
"faith_114": ("Com que frequência ordena o Alcorão lembrar Allah, na sura Al-Ahzab?", ["Muito, de manhã e à tarde", "Uma vez por ano", "Uma vez por semana", "Só em viagem"], "«Ó crentes! Lembrai muito Allah, e glorificai-O de manhã e à tarde»."),
"faith_115": ("Sobre que meditam «os dotados de entendimento», no fim da sura Al 'Imran?", ["Sobre a criação dos céus e da terra, em toda postura", "Sobre as colheitas", "Sobre as caravanas", "Sobre as genealogias"], "«Aqueles que lembram Allah de pé, sentados e deitados, e meditam sobre a criação dos céus e da terra»."),
"faith_116": ("O que ordena o Alcorão fazer depois de tomada uma decisão?", ["Confiar em Allah", "Esperar um sinal", "Perguntar a um adivinho", "Desistir"], "«E quando tiveres decidido, confia em Allah: Allah ama os que n'Ele confiam»."),
"faith_117": ("Para quem dirige a sura Ash-Sharh o anseio, uma vez concluída a tarefa?", ["Para o seu Senhor", "Para o descanso", "Para a família", "Para as pessoas"], "«Quando ficares livre, esforça-te; e ao teu Senhor dirige o teu anseio»."),
"faith_118": ("Com que compara a sura Al-Hadid a vida deste mundo?", ["Com uma chuva cuja vegetação encanta, depois amarelece e vira detrito", "Com uma longa viagem", "Com uma montanha", "Com um oceano"], "«Sabei que a vida deste mundo não é senão jogo e distração… como uma chuva cuja vegetação encanta os lavradores; depois seca, vê-la amarelecer e torna-se detrito»."),
"faith_119": ("O que declara o Alcorão melhor do que os bens e os filhos, adorno deste mundo?", ["As boas obras que perduram", "O ouro", "A fama", "As terras"], "«Os bens e os filhos são o adorno da vida deste mundo, mas as boas obras que perduram são melhor recompensa junto ao teu Senhor»."),
"faith_120": ("Que pergunta faz o Alcorão sobre o fim da criação do homem?", ["«Julgáveis que vos havíamos criado sem propósito?»", "«Quem vos nomeou?»", "«Para onde ireis?»", "«Quantos sois?»"], "«Julgáveis que vos havíamos criado sem propósito e que não seríeis devolvidos a Nós?»"),
"faith_121": ("Que promessa faz o Alcorão a quem lembra Allah?", ["«Lembrai-Me e Eu lembrar-vos-ei»", "«Sereis ricos»", "«Vivereis muito»", "«Viajareis»"], "«Lembrai-Me, pois, e Eu lembrar-vos-ei. E sede-Me gratos e não Me negueis»."),
"faith_122": ("A quem ordena o Alcorão remeter as disputas?", ["A Allah e ao Mensageiro ﷺ", "Aos anciãos", "Ao mercado", "Aos poetas"], "«E se disputardes sobre algo, remetei-o a Allah e ao Mensageiro, se credes em Allah e no Último Dia»."),
"faith_123": ("Como descreve a sura Al-Anfal os corações dos crentes ao mencionar-se Allah?", ["Os seus corações estremecem e a sua fé aumenta com a recitação", "Endurecem", "Adormecem", "Esquecem"], "«Os crentes são apenas aqueles cujos corações estremecem quando se menciona Allah, e cuja fé aumenta quando lhes são recitados os Seus versículos»."),
"faith_124": ("O que ordena o Alcorão dedicar por inteiro ao Senhor dos mundos?", ["A oração, os atos de devoção, a vida e a morte", "O comércio", "As colheitas", "As viagens"], "«Diz: a minha oração, os meus atos de devoção, a minha vida e a minha morte pertencem a Allah, Senhor dos mundos»."),
"faith_125": ("Que condição põe a sura Al-Bayyina à adoração ordenada?", ["Adorar Allah com devoção sincera e exclusiva", "Adorar em público", "Adorar por escrito", "Adorar só em grupo"], "«Não lhes foi ordenado senão adorar Allah, com devoção sincera, estabelecer a oração e dar o zakat»."),
"faith_126": ("O que descreve o Alcorão como correndo nos jardins prometidos aos piedosos?", ["Rios", "Caminhos", "Pontes", "Poços"], "O Alcorão descreve repetidamente os jardins «sob os quais correm os rios»."),
"faith_127": ("O que diz o Alcorão do que está oculto aos crentes como recompensa?", ["Ninguém sabe que alegria dos olhos lhes está reservada", "Tudo está descrito em detalhe", "São riquezas", "São reinos"], "«Ninguém sabe que alegria dos olhos lhes está reservada, como recompensa pelo que faziam»."),
"faith_128": ("O que promete o Alcorão aos que praticam o bem, além da melhor recompensa?", ["Um acréscimo (ziyada)", "Um adiamento", "Um reino", "Um livro"], "«Aos que praticam o bem cabe o melhor e ainda mais»."),
"faith_129": ("Como descreve o Alcorão o acolhimento dos piedosos à entrada do Paraíso?", ["«A paz esteja convosco! Fostes bons: entrai para nele morar»", "Em silêncio", "Após um longo julgamento", "Um a um sem palavra"], "«Os seus guardiões dir-lhes-ão: “A paz esteja convosco; fostes bons: entrai para nele morar eternamente”»."),
"faith_130": ("Para que ordena o Alcorão apressar-se, na sura Al 'Imran?", ["Para um perdão do seu Senhor e um Paraíso tão amplo como os céus e a terra", "Para o mercado", "Para a viagem", "Para a riqueza"], "«E apressai-vos para um perdão do vosso Senhor e para um Jardim tão amplo como os céus e a terra, preparado para os piedosos»."),
"faith_131": ("Que responsabilidade impõe o Alcorão ao crente em relação à sua família?", ["Preservá-los, e a si próprio, de um Fogo", "Enriquecê-los", "Ensinar-lhes línguas", "Levá-los em viagem"], "«Ó crentes! Preservai-vos a vós próprios e às vossas famílias de um Fogo cujo combustível são os homens e as pedras»."),
"faith_132": ("Como define o versículo 2:177 a verdadeira piedade (al-birr)?", ["Crer em Allah, no Último Dia, nos anjos, no Livro e nos profetas, e dar dos bens", "Voltar o rosto para leste ou oeste", "Só jejuar", "Viajar"], "«A piedade não consiste em voltar o rosto para o oriente ou o ocidente, mas em crer em Allah, no Último Dia, nos anjos, no Livro e nos profetas»."),
"faith_133": ("Quem verá as obras realizadas, segundo a sura At-Tawba?", ["Allah, o Seu Mensageiro ﷺ e os crentes", "Ninguém", "Só os anjos", "Os reis"], "«E diz: agi, pois Allah verá as vossas obras, e também o Seu Mensageiro e os crentes»."),
"faith_134": ("Com que afirmação termina a sura Al-Ikhlas?", ["«E não há ninguém que se Lhe iguale»", "«Ele é o maior»", "«Ele está perto»", "«Ele é o primeiro»"], "«E não há ninguém que se Lhe iguale»."),
"faith_135": ("Que quatro nomes reúne a sura Al-Hadid num só versículo?", ["O Primeiro, o Último, o Manifesto e o Oculto", "O Rei, o Santo, a Paz, o Fiel", "O Criador, o Originador, o Formador, o Sábio", "O Vivente, o Sustentador, o Ouvinte, o Vidente"], "«Ele é o Primeiro e o Último, o Manifesto e o Oculto, e Ele conhece todas as coisas»."),
"faith_136": ("Que nomes enumera o fim da sura Al-Hashr depois de «o Soberano»?", ["O Santo, a Paz, o que dá segurança, o Custódio", "O Criador, o Formador", "O Perdoador, o Misericordioso", "O Ouvinte, o Vidente"], "«Ele é Allah, o Soberano, o Santo, a Paz, o que dá segurança, o Custódio, o Poderoso»."),
"faith_137": ("Como se chama a fórmula «Não há deus senão Allah, Muhammad é o Seu Mensageiro»?", ["A shahada (o testemunho de fé)", "A basmala", "A takbira", "A tasmiya"], "A shahada é a primeira palavra do islão e o primeiro dos seus pilares."),
"faith_138": ("Como se chama a fórmula «Allahu akbar»?", ["O takbir", "O tahlil", "O tasbih", "O tahmid"], "O takbir é «Allahu akbar», o tasbih «subhan Allah», o tahmid «al-hamdu lillah» e o tahlil «la ilaha illa-llah»."),
"faith_139": ("Como se chama a fórmula «Em nome de Allah, o Clemente, o Misericordioso»?", ["A basmala", "A hamdala", "A hawqala", "O istirja'"], "A basmala abre todas as suras menos uma; a hawqala é «la hawla wa la quwwata illa billah»."),
"faith_140": ("Que palavras ensina o Alcorão a dizer quando sobrevém uma desgraça?", ["«Somos de Allah e a Ele retornaremos»", "«Porquê eu?»", "«Há de passar»", "«É o destino dos homens»"], "«Aqueles que, quando os atinge uma desgraça, dizem: “Somos de Allah e a Ele retornaremos”»."),
"faith_141": ("O que ordena dizer o Alcorão ao anunciar que se fará algo amanhã?", ["«Se Allah quiser» (in sha' Allah)", "«Está prometido»", "«Sem falta»", "«Juro»"], "«E nunca digas de algo: “Fá-lo-ei amanhã”, sem acrescentar: “se Allah quiser”»."),
"faith_142": ("Que conhecimento reserva o Alcorão só a Allah, no fim da sura Luqman?", ["A Hora, a chuva, o que há nos ventres, o que se ganhará amanhã e onde se morrerá", "O número das estrelas", "Os nomes dos reis", "A conta dos dias"], "«Allah tem o conhecimento da Hora, faz descer a chuva e sabe o que há nos ventres. Ninguém sabe o que ganhará amanhã nem em que terra morrerá»."),
"faith_143": ("O que diz o Alcorão sobre o prazo fixado para cada comunidade?", ["Quando chega, não se atrasa nem se adianta uma hora", "É modificável", "Allah não o conhece", "Depende dos reis"], "«Cada comunidade tem um prazo: quando chega o seu prazo, não o atrasam nem o adiantam uma hora»."),
"faith_144": ("O que promete o Alcorão a quem pratica o bem, homem ou mulher, sendo crente?", ["Uma vida boa, e uma recompensa segundo o melhor das suas obras", "A riqueza", "O poder", "A fama"], "«A quem praticar o bem, homem ou mulher, sendo crente, faremos viver uma vida boa»."),
"faith_145": ("Que distinção estabelece o Alcorão entre «islão» e «fé» na sura Al-Hujurat?", ["Dizer «submetemo-nos» ainda não é a fé entrar nos corações", "São a mesma palavra", "A fé precede sempre", "O islão é só para os sábios"], "«Dizem os beduínos: “Cremos”. Diz: “Ainda não credes; dizei antes: submetemo-nos, pois a fé ainda não entrou nos vossos corações”»."),
"faith_146": ("Que regra enuncia a sura Al-Ma'ida sobre a vida de uma só pessoa?", ["Quem mata uma pessoa é como se matasse toda a humanidade; quem salva uma, como se a salvasse toda", "Cada vida conta por uma", "Só contam os parentes", "Só conta o número"], "«Quem matar uma pessoa sem que seja por outra ou por corrupção na terra, será como se tivesse matado toda a humanidade; e quem salvar uma vida, será como se tivesse salvado toda a humanidade»."),
"faith_147": ("Por quanto multiplica o Alcorão a recompensa da boa ação?", ["Por dez", "Por dois", "Por cem", "Não é multiplicada"], "«Quem vier com uma boa ação terá dez vezes outro tanto; e quem vier com uma má só será retribuído com o seu equivalente»."),
"faith_148": ("Como descreve a sura Fatir a relação dos homens com Allah?", ["Eles são os pobres, e Allah é o Rico, o Digno de louvor", "São Seus sócios", "São independentes", "São Seus credores"], "«Ó homens! Vós sois os pobres, necessitados de Allah, e Allah é o Rico, o Digno de louvor»."),
"faith_149": ("Que quatro qualidades salvam da perdição, segundo a sura Al-'Asr?", ["A fé, as boas obras, exortar-se à verdade e à paciência", "A riqueza, a força, a beleza, a astúcia", "O silêncio, o sono, o retiro, o jejum", "A viagem, o comércio, a escrita, a leitura"], "«Pelo tempo! O homem está em perdição, salvo os que creem, praticam o bem, se exortam à verdade e se exortam à paciência»."),
"faith_150": ("Em que declaram crer os crentes, no penúltimo versículo da sura Al-Baqara?", ["Em Allah, nos Seus anjos, nos Seus livros e nos Seus mensageiros", "Num só livro", "Num só anjo", "Nos seus antepassados"], "«O Mensageiro crê no que lhe foi revelado pelo seu Senhor, e também os crentes: todos creem em Allah, nos Seus anjos, nos Seus livros e nos Seus mensageiros»."),
}
